"use strict";(self.webpackChunksalat_e_mustaqeem_client=self.webpackChunksalat_e_mustaqeem_client||[]).push([[3198],{83198:a=>{a.exports=JSON.parse('{"categories":{"prayer-times":"Horarios de oraci\xf3n","location":"Ubicaci\xf3n","setup":"Tus ajustes de oraci\xf3n","athan":"Adhan","scheduled":"Adhan autom\xe1tico","quran":"Cor\xe1n y reproducci\xf3n","hifz":"Hifz Coach","masjid":"Mi mezquita","ramadan":"Ramad\xe1n","islamic-calendar":"Qibla y calendario isl\xe1mico","fasting":"Ayunos de la Sunnah","remembrance":"Adhkar, tasbih y recordatorios diarios","help":"Primeros pasos"},"commands":{"Alexa, ask Muslim Companion what is my next prayer":{"does":"Dice la pr\xf3xima oraci\xf3n, su hora y cu\xe1nto falta, adem\xe1s de la iqamah de tu mezquita si sigues una.","say":["Alexa, pregunta a Muslim Companion cu\xe1l es mi pr\xf3xima oraci\xf3n","Alexa, pregunta a Muslim Companion cu\xe1ndo es la pr\xf3xima oraci\xf3n"]},"Alexa, ask Muslim Companion when is Maghrib":{"does":"Dice la hora de una oraci\xf3n hoy (despu\xe9s de Isha, Fajr es la de ma\xf1ana).","say":["Alexa, pregunta a Muslim Companion cu\xe1ndo es Maghrib","Alexa, pregunta a Muslim Companion a qu\xe9 hora es Fajr"]},"Alexa, ask Muslim Companion for today\'s prayer times":{"does":"Lee todos los horarios de hoy. En un Echo Show tambi\xe9n los muestra en pantalla con la pr\xf3xima oraci\xf3n y una cuenta atr\xe1s.","say":["Alexa, pide a Muslim Companion los horarios de oraci\xf3n de hoy","Alexa, pide a Muslim Companion los horarios de oraci\xf3n"]},"Alexa, ask Muslim Companion to use my Echo\'s location":{"does":"Ajusta tus horarios con la direcci\xf3n de tu Echo (tras permitir la direcci\xf3n del dispositivo en la app Alexa). Solo se guardan la ciudad y coordenadas aproximadas.","say":["Alexa, pide a Muslim Companion que use la ubicaci\xf3n de mi Echo","Alexa, pide a Muslim Companion que actualice mi ubicaci\xf3n"]},"Alexa, ask Muslim Companion for prayer times where I am":{"does":"En la app Alexa del m\xf3vil: los horarios donde est\xe1s ahora, solo para esa respuesta. Tus Adhans en casa no cambian.","say":["Alexa, pide a Muslim Companion los horarios de oraci\xf3n donde estoy","Alexa, pide a Muslim Companion los horarios de oraci\xf3n cerca de m\xed"]},"Yes":{"does":"Responde a una pregunta de Muslim Companion, por ejemplo si usar la ubicaci\xf3n de tu Echo.","say":["S\xed","No"]},"Alexa, ask Muslim Companion to read my prayer settings":{"does":"Dice tu ubicaci\xf3n, m\xe9todo de c\xe1lculo y madhab para Asr, y c\xf3mo cambiarlos.","say":["Alexa, pide a Muslim Companion que lea mis ajustes de oraci\xf3n"]},"Alexa, ask Muslim Companion to set my calculation method to Umm al-Qura":{"does":"Cambia el c\xe1lculo de tus horarios: ISNA, Liga Musulmana Mundial, Umm al-Qura, Egipto, Karachi, Golfo, Kuwait, Catar, Singapur, Francia, Turqu\xeda, Rusia, Teher\xe1n o Jafari. Alexa confirma con tu nueva pr\xf3xima oraci\xf3n y te dice c\xf3mo volver atr\xe1s.","say":["Alexa, pide a Muslim Companion que ponga mi m\xe9todo de c\xe1lculo en Umm al-Qura","Alexa, dile a Muslim Companion que use el m\xe9todo de la Liga Musulmana Mundial","Alexa, dile a Muslim Companion que mi mezquita usa ISNA"]},"Alexa, ask Muslim Companion to set my madhab to Hanafi":{"does":"Ajusta la hora de Asr: hanaf\xed (Asr m\xe1s tarde) o est\xe1ndar para shafi\xed, malik\xed y hanbal\xed.","say":["Alexa, pide a Muslim Companion que ponga mi madhab en hanaf\xed","Alexa, dile a Muslim Companion que sigo el madhab hanaf\xed","Alexa, pide a Muslim Companion que ponga mi madhab en est\xe1ndar"]},"Alexa, ask Muslim Companion which calculation method should I use":{"does":"Sugiere el m\xe9todo m\xe1s usado donde vives (por ejemplo ISNA en Norteam\xe9rica, la Diyanet en Turqu\xeda) y ofrece cambiarlo: di s\xed o no.","say":["Alexa, pregunta a Muslim Companion qu\xe9 m\xe9todo de c\xe1lculo deber\xeda usar"]},"Alexa, ask Muslim Companion what calculation method am I using":{"does":"Otras formas de preguntar por tus ajustes.","say":["Alexa, pregunta a Muslim Companion qu\xe9 m\xe9todo de c\xe1lculo estoy usando","Alexa, pregunta a Muslim Companion cu\xe1l es mi madhab"]},"Alexa, ask Muslim Companion to play athan":{"does":"Reproduce el Adhan ahora, seguido de las duas y el Cor\xe1n que elegiste. Voces que puedes nombrar: La Meca, Medina, Mishary, Zahrani\u2026","say":["Alexa, pide a Muslim Companion que ponga el adhan","Alexa, pide a Muslim Companion que ponga el adhan de La Meca"]},"Alexa, ask Muslim Companion to play fajr athan":{"does":"Reproduce el Adhan de esa oraci\xf3n (Fajr tiene su propia voz).","say":["Alexa, pide a Muslim Companion que ponga el adhan de fajr","Alexa, pide a Muslim Companion que ponga el adhan de maghrib"]},"Alexa, ask Muslim Companion to test athan":{"does":"Reproduce el Adhan una vez para comprobar el sonido de este Echo.","say":["Alexa, pide a Muslim Companion que pruebe el adhan"]},"Alexa, ask Muslim Companion what is my scheduled athan status":{"does":"Te dice si el Adhan autom\xe1tico est\xe1 activado.","say":["Alexa, pregunta a Muslim Companion el estado de mi adhan programado"]},"Alexa, ask Muslim Companion to enable scheduled athan":{"does":"Activa el Adhan autom\xe1tico. Suena en cada oraci\xf3n a trav\xe9s de tu rutina de Alexa (ver la gu\xeda de configuraci\xf3n).","say":["Alexa, pide a Muslim Companion que active el adhan programado"]},"Alexa, ask Muslim Companion to disable scheduled athan":{"does":"Desactiva el Adhan autom\xe1tico en todas las oraciones hasta que lo vuelvas a activar.","say":["Alexa, pide a Muslim Companion que desactive el adhan programado"]},"Alexa, ask Muslim Companion to play Surah Al-Kahf":{"does":"Reproduce cualquier sura por nombre o n\xfamero, dicha a tu manera (Fatiha o Fateha, Baqarah o Baqara, Nisa\u2026), con tu recitador o el que nombres (Qari Badar, Maher, Al-Muaiqly, Sudais\u2026), o con traducci\xf3n al ingl\xe9s o urdu tras cada aleya.","say":["Alexa, pide a Muslim Companion que ponga la sura Al-Kahf","Alexa, pide a Muslim Companion que ponga la sura Baqarah de Qari Badar","Alexa, pide a Muslim Companion que ponga la Fatiha de Maher","Alexa, pide a Muslim Companion que ponga la sura n\xfamero 36","Alexa, pide a Muslim Companion que ponga la sura Yasin con traducci\xf3n al ingl\xe9s"]},"Alexa, ask Muslim Companion which reciters do you have":{"does":"Enumera los recitadores, o los que empiezan por una letra. Si Alexa no conoce el recitador que nombras, sugiere los que empiezan por la misma letra.","say":["Alexa, pregunta a Muslim Companion qu\xe9 recitadores tiene","Alexa, pregunta a Muslim Companion qu\xe9 recitadores empiezan por S"]},"Alexa, ask Muslim Companion to turn on Friday Kahf":{"does":"Cada viernes, la sura Al-Kahf suena despu\xe9s del Adhan de Fajr (o Dhuhr, en el panel).","say":["Alexa, pide a Muslim Companion que active Al-Kahf del viernes","Alexa, pide a Muslim Companion que desactive Al-Kahf del viernes"]},"Alexa, next":{"does":"Mientras suena el Cor\xe1n: sura siguiente o anterior. Durante el Adhan y las duas, \xabsiguiente\xbb avanza.","say":["Alexa, siguiente","Alexa, anterior"]},"Alexa, start over":{"does":"Vuelve a empezar la sura actual.","say":["Alexa, empieza de nuevo"]},"Alexa, pause":{"does":"Pausa la recitaci\xf3n y contin\xfaa desde el mismo punto.","say":["Alexa, pausa","Alexa, contin\xfaa"]},"Alexa, stop":{"does":"Detiene el Adhan o la recitaci\xf3n en cualquier momento.","say":["Alexa, para","Alexa, cancela"]},"Alexa, ask Muslim Companion how far am I in the Quran":{"does":"Te dice tu recorrido por el Cor\xe1n: tiempo de escucha y cu\xe1nto del jatm has escuchado.","say":["Alexa, pregunta a Muslim Companion por d\xf3nde voy en el Cor\xe1n"]},"Alexa, shuffle":{"does":"Explica c\xf3mo elegir Cor\xe1n aleatorio o continuo en la p\xe1gina Programa del Cor\xe1n.","say":["Alexa, aleatorio","Alexa, repetir"]},"Alexa, ask Muslim Companion to start Hifz":{"does":"Reproduce tu lecci\xf3n actual: cada aleya repetida y luego toda la lecci\xf3n. En un Echo Show la aleya aparece en pantalla.","say":["Alexa, pide a Muslim Companion que empiece el Hifz"]},"Alexa, tell Muslim Companion I memorized it":{"does":"Marca la lecci\xf3n como memorizada y pasa a la siguiente.","say":["Alexa, dile a Muslim Companion que ya la memoric\xe9"]},"Alexa, ask Muslim Companion to repeat each ayah five times":{"does":"Ajusta cu\xe1ntas veces se repite cada aleya: 1, 3, 5, 7 o 10.","say":["Alexa, pide a Muslim Companion que repita cada aleya cinco veces"]},"Alexa, ask Muslim Companion how is my Hifz":{"does":"Te dice cu\xe1ntas aleyas has memorizado y tu lecci\xf3n actual.","say":["Alexa, pregunta a Muslim Companion c\xf3mo va mi Hifz"]},"Alexa, ask Muslim Companion when is iqamah":{"does":"Dice la pr\xf3xima iqamah en la mezquita que sigues.","say":["Alexa, pregunta a Muslim Companion cu\xe1ndo es la iqamah"]},"Alexa, ask Muslim Companion when is jumuah":{"does":"Dice la hora u horas del Yumu\'a de esta semana en tu mezquita.","say":["Alexa, pregunta a Muslim Companion cu\xe1ndo es el Yumu\'a"]},"Alexa, ask Muslim Companion to turn on Ramadan mode":{"does":"Activa o desactiva el modo Ramad\xe1n: recordatorio del suhur, iftar en Maghrib y recitaci\xf3n de Tarawih despu\xe9s de Isha.","say":["Alexa, pide a Muslim Companion que active el modo Ramad\xe1n","Alexa, pide a Muslim Companion que desactive el modo Ramad\xe1n"]},"Alexa, ask Muslim Companion is Ramadan mode on":{"does":"Te dice si el modo Ramad\xe1n est\xe1 activado.","say":["Alexa, pregunta a Muslim Companion si el modo Ramad\xe1n est\xe1 activado"]},"Alexa, ask Muslim Companion when is suhoor":{"does":"Dice cu\xe1ndo termina el suhur (Fajr) y cu\xe1ndo es el iftar (Maghrib).","say":["Alexa, pregunta a Muslim Companion cu\xe1ndo es el suhur","Alexa, pregunta a Muslim Companion cu\xe1ndo es el iftar"]},"Alexa, ask Muslim Companion which way is the Qibla":{"does":"Dice la direcci\xf3n de la Qibla desde tu ubicaci\xf3n en grados desde el norte verdadero y como punto cardinal, y a qu\xe9 distancia est\xe1 La Meca.","say":["Alexa, pregunta a Muslim Companion hacia d\xf3nde est\xe1 la Qibla","Alexa, pregunta a Muslim Companion d\xf3nde est\xe1 la Qibla"]},"Alexa, ask Muslim Companion what is the Hijri date":{"does":"Dice la fecha h\xe9gira de hoy (la misma que la app y tu Echo Show) y si hoy es un d\xeda especial.","say":["Alexa, pregunta a Muslim Companion cu\xe1l es la fecha h\xe9gira","Alexa, pregunta a Muslim Companion qu\xe9 fecha isl\xe1mica es hoy"]},"Alexa, ask Muslim Companion when is Ramadan":{"does":"Cu\xe1ndo son Ramad\xe1n, el Eid, Ashura, Arafah, el A\xf1o Nuevo isl\xe1mico, las diez \xfaltimas noches o los d\xedas blancos, con cuenta atr\xe1s. Las fechas siguen Umm al-Qura y pueden variar un d\xeda donde la luna se avista localmente.","say":["Alexa, pregunta a Muslim Companion cu\xe1ndo es Ramad\xe1n","Alexa, pregunta a Muslim Companion cu\xe1ntos d\xedas faltan para el Eid","Alexa, pregunta a Muslim Companion cu\xe1ndo son los d\xedas blancos"]},"Alexa, ask Muslim Companion when is the next Sunnah fast":{"does":"El pr\xf3ximo ayuno de la Sunnah: lunes y jueves, d\xedas blancos, Arafah, Ashura y los seis d\xedas de Shawwal.","say":["Alexa, pregunta a Muslim Companion cu\xe1ndo es el pr\xf3ximo ayuno de la Sunnah","Alexa, pregunta a Muslim Companion si debo ayunar ma\xf1ana"]},"Alexa, ask Muslim Companion to turn on fasting reminders":{"does":"Un recordatorio despu\xe9s de Isha la v\xedspera de un ayuno de la Sunnah, a trav\xe9s de tu rutina de Muslim Companion.","say":["Alexa, pide a Muslim Companion que active los recordatorios de ayuno","Alexa, pide a Muslim Companion que desactive los recordatorios de ayuno"]},"Alexa, ask Muslim Companion to play the morning adhkar":{"does":"Ayat al-Kursi y luego Al-Ijlas, Al-Falaq y An-Nas tres veces cada una, recitadas.","say":["Alexa, pide a Muslim Companion que ponga los adhkar de la ma\xf1ana","Alexa, pide a Muslim Companion que ponga los adhkar de la tarde"]},"Alexa, ask Muslim Companion to turn on morning and evening adhkar":{"does":"Reproduce los adhkar de la ma\xf1ana tras Fajr y los de la tarde tras Asr cada d\xeda (o Maghrib, en el panel).","say":["Alexa, pide a Muslim Companion que active los adhkar de la ma\xf1ana y la tarde","Alexa, pide a Muslim Companion que desactive los adhkar de la tarde"]},"Alexa, ask Muslim Companion to start tasbih":{"does":"Cuenta el dhikr contigo a un ritmo suave. Sin dhikr indicado, gu\xeda el tasbih tras la oraci\xf3n: 33 SubhanAllah, 33 Alhamdulillah y 34 Allahu Akbar. En un Echo Show, toca la pantalla para contar.","say":["Alexa, pide a Muslim Companion que empiece el tasbih","Alexa, pide a Muslim Companion que cuente 33 subhanallah"]},"Alexa, ask Muslim Companion for today\'s dua":{"does":"Una breve dua, hadiz o Nombre de Allah del d\xeda con su fuente, revisado por un sabio antes de publicarse.","say":["Alexa, pide a Muslim Companion la dua de hoy","Alexa, pide a Muslim Companion el hadiz de hoy","Alexa, pide a Muslim Companion el nombre de Allah del d\xeda"],"soonNote":"Pr\xf3ximamente: cada dua, hadiz y Nombre lo revisa antes un sabio"},"Alexa, open Muslim Companion":{"does":"Abre la skill (reproduce el Adhan de la oraci\xf3n actual).","say":["Alexa, abre Muslim Companion"]},"Alexa, ask Muslim Companion for help":{"does":"Enumera lo que puedes preguntar.","say":["Alexa, pide ayuda a Muslim Companion"]},"Alexa, ask Muslim Companion to link my phone":{"does":"Vincula este Echo con tu cuenta de Salat-e-Mustaqeem en el tel\xe9fono con el c\xf3digo de seis d\xedgitos de la app (M\xe1s, luego Alexa), para que tu progreso de Hifz aparezca en el tel\xe9fono.","say":["Alexa, pide a Muslim Companion que vincule mi tel\xe9fono","Alexa, pide a Muslim Companion que vincule mi tel\xe9fono con el c\xf3digo 123456"]}}}')}}]);